import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { ResponsiveContainer, AreaChart, Area, XAxis, YAxis, Tooltip, CartesianGrid, PieChart, Pie, Cell, BarChart, Bar, Legend } from 'recharts';
import { Wallet, LayoutDashboard, ArrowLeftRight, ChartNoAxesCombined, Target, Landmark, SlidersHorizontal, Plus, ArrowUpRight, ArrowDownLeft, ArrowRight, ChevronLeft, ChevronRight, Download, Search, X, Pencil, Trash2, Moon, Sun, Sparkles, ShieldCheck, TrendingUp, Coffee, Car, House, ShoppingBag, Zap, CircleDollarSign, Check, Menu, Leaf, PiggyBank } from 'lucide-react';
import './styles.css';
import AuthGate from './AuthGate.jsx';
import { accountFlow } from './account-flow.js';

const today = () => new Date().toLocaleDateString('en-CA');
const initialMonth = today().slice(0, 7);
const format = (value, compact = false) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: compact ? 0 : 2, minimumFractionDigits: 0, ...(compact && Math.abs(value) >= 1000000 ? { notation: 'compact' } : {}) }).format(value ?? 0);
const sum = (rows) => rows.reduce((total, row) => total + Math.round(row.amount * 100), 0) / 100;
const palette = ['#25876c', '#edb86e', '#8a9ec6', '#c599bb', '#82bcb2', '#d98f77', '#aba485', '#7f8b9d'];
const categoryIcon = (category) => ({ Food: Coffee, Transport: Car, Rent: House, Shopping: ShoppingBag, Utilities: Zap, Salary: Landmark })[category] ?? CircleDollarSign;
const monthLabel = (month) => new Date(`${month}-02T12:00:00`).toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
async function request(path, method = 'GET', body) {
  const response = await fetch(`/api${path}`, { method, ...(body !== undefined ? { headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : {}) });
  const result = await response.json();
  if (response.status === 401) window.dispatchEvent(new Event('pocket-session-expired'));
  if (!response.ok) throw new Error(result.error || 'Unable to complete the request');
  return result;
}

function Empty({ title = 'A fresh start, a clearer picture.', text = 'Add your first record to start making sense of your money.', action }) {
  return <div className="empty"><div className="empty-icon"><Leaf size={28} /></div><h3>{title}</h3><p>{text}</p>{action}</div>;
}
function Progress({ value, tone = '' }) { return <div className={`progress ${tone}`} role="progressbar" aria-valuenow={Math.round(Math.max(0, Math.min(100, value || 0)))} aria-valuemin={0} aria-valuemax={100} aria-label="Progress"><span style={{ width: `${Math.max(0, Math.min(100, value || 0))}%` }} /></div>; }
function IconButton({ title, children, ...props }) { return <button className="icon-button" title={title} aria-label={title} {...props}>{children}</button>; }
function PanelHeading({ title, subtitle, action }) { return <div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }

function App({ signOut, signingOut }) {
  const [page, setPage] = useState('Overview');
  const [month, setMonth] = useState(initialMonth);
  const [data, setData] = useState(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [modal, setModal] = useState(null);
  const [dark, setDark] = useState(() => localStorage.getItem('pocket-theme') === 'dark');
  const [mobileMenu, setMobileMenu] = useState(false);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const [accountId, setAccountId] = useState('');
  const [transactionType, setTransactionType] = useState('');
  const [investmentId, setInvestmentId] = useState('');
  const [smartInput, setSmartInput] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; localStorage.setItem('pocket-theme', dark ? 'dark' : 'light'); }, [dark]);
  useEffect(() => {
    let active = true;
    request(`/state?month=${month}`).then((result) => { if (active) { setData(result); setError(''); } }).catch((e) => { if (active) setError(e.message); });
    return () => { active = false; };
  }, [month]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 4500); return () => clearTimeout(timer); }, [notice]);
  const reload = async () => setData(await request(`/state?month=${month}`));
  const run = async (fn, message) => {
    if (busy) return;
    setBusy(true); setError('');
    try { await fn(); await reload(); if (message) setNotice(message); } catch (e) { setError(e.message); } finally { setBusy(false); }
  };
  const open = (kind, value = null) => { setError(''); setModal({ kind, value }); };
  const remove = (kind, item) => open('delete', { kind, item });
  const navigate = (next) => { setPage(next); setMobileMenu(false); };
  const moveMonth = (direction) => {
    const date = new Date(`${month}-02T12:00:00`);
    date.setMonth(date.getMonth() + direction);
    const next = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
    if (next >= '2000-01' && next <= '2100-12') setMonth(next);
  };
  const transactions = data?.transactions ?? [];
  const selected = transactions.filter((t) => t.date.startsWith(month));
  const expenses = selected.filter((t) => t.type === 'expense');
  const income = sum(selected.filter((t) => t.type === 'income'));
  const spending = sum(expenses);
  const bankTotal = data ? Object.values(data.balances).reduce((total, balance) => total + Math.round(balance * 100), 0) / 100 : 0;
  const assets = data?.investments.filter((i) => i.type === 'asset').reduce((total, i) => total + i.value, 0) ?? 0;
  const liabilities = data?.investments.filter((i) => i.type === 'liability').reduce((total, i) => total + i.value, 0) ?? 0;
  const netWorth = bankTotal + assets - liabilities + (data?.goalNetWorthTotal ?? 0);
  const budgetItems = (data?.categoryBudgetStatus ?? []).filter((item) => item.includeInTotal !== false);
  const budget = budgetItems.length ? {
    spent: budgetItems.reduce((total, item) => total + item.spent, 0),
    available: budgetItems.reduce((total, item) => total + item.available, 0),
    remaining: budgetItems.reduce((total, item) => total + item.remaining, 0),
  } : null;
  const grouped = Object.entries(expenses.reduce((map, t) => ({ ...map, [t.category]: (map[t.category] ?? 0) + Math.round(t.amount * 100) }), {})).map(([name, value]) => ({ name, value: value / 100 })).sort((a, b) => b.value - a.value);
  const filtered = selected.filter((t) => (!transactionType || t.type === transactionType) && (!category || t.category === category) && (!accountId || t.accountId === accountId || t.fromType === 'account' && t.fromId === accountId || t.toType === 'account' && t.toId === accountId) && (!investmentId || t.fromType === 'investment' && t.fromId === investmentId || t.toType === 'investment' && t.toId === investmentId) && `${t.notes} ${t.category} ${t.fromName ?? ''} ${t.toName ?? ''}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => b.date.localeCompare(a.date));
  const activeGoals = data?.goals.filter((g) => g.status === 'active') ?? [];
  const exportHref = `/api/export?${new URLSearchParams({ month, ...(transactionType ? { type: transactionType } : {}), ...(investmentId ? { investmentId } : {}), ...(category ? { category } : {}), ...(accountId ? { accountId } : {}), ...(search ? { search } : {}) })}`;
  const addTransaction = () => data?.accounts.length ? open('transactions') : open('accounts');
  const navigation = [{ name: 'Overview', icon: LayoutDashboard }, { name: 'Transactions', icon: ArrowLeftRight }, { name: 'Budgets', icon: Wallet }, { name: 'Goals', icon: Target }, { name: 'Investments', icon: ChartNoAxesCombined }, { name: 'Accounts', icon: Landmark }, { name: 'Reports', icon: SlidersHorizontal }];
  const chartData = Array.from({ length: new Date(Number(month.slice(0, 4)), Number(month.slice(5)), 0).getDate() }, (_, index) => {
    const day = index + 1;
    const rows = selected.filter((t) => Number(t.date.slice(8)) <= day);
    return { day, Income: sum(rows.filter((t) => t.type === 'income')), Expenses: sum(rows.filter((t) => t.type === 'expense')) };
  });

  function transactionTable(rows, limit) {
    if (!rows.length) return <Empty title="No transactions here yet" text="Log an expense or income, and your story starts here." action={<button className="button secondary" onClick={addTransaction}><Plus size={16} /> Add transaction</button>} />;
    return <div className="table-scroll"><table><thead><tr><th>Transaction</th><th>Category</th><th>Account</th><th>Date</th><th className="amount-col">Amount</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{rows.slice(0, limit ?? rows.length).map((t) => {
      if (t.type === 'transfer') {
        const endpointName = (type, id, fallback) => (type === 'account' ? data.accounts : data.investments).find((item) => item.id === id)?.name ?? fallback;
        const route = `${endpointName(t.fromType, t.fromId, t.fromName)} → ${endpointName(t.toType, t.toId, t.toName)}`;
        return <tr key={t.id}><td><div className="transaction-name"><span className="category-icon transfer"><ArrowLeftRight size={18} /></span><div><strong>{t.notes || 'Self transfer'}</strong><small>Transfer · not income or spending</small></div></div></td><td><span className="tag">Transfer</span></td><td className="muted">{route}</td><td className="muted nowrap">{t.date}</td><td className="amount-col">{t.fromType === 'investment' ? <><span>Deducted {format(t.amount)}</span><small className="transfer-received">Received {format(t.receivedAmount)}</small></> : format(t.amount)}</td><td><span className="muted" title="Transfers are read-only. Record a separate correcting transfer if needed.">Read-only</span></td></tr>;
      }
      const Icon = categoryIcon(t.category);
      return <tr key={t.id}><td><div className="transaction-name"><span className={`category-icon ${t.type === 'income' ? 'income' : ''}`}><Icon size={18} /></span><div><strong>{t.notes || t.category}</strong><small>{t.type === 'income' ? 'Money in' : 'Money out'}{data.insights.anomalies.includes(t.id) ? ' · Unusually high' : ''}</small></div></div></td><td><span className="tag">{t.category}</span></td><td className="muted">{data.accounts.find((a) => a.id === t.accountId)?.name ?? 'Unknown account'}</td><td className="muted nowrap">{new Date(`${t.date}T12:00:00`).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</td><td className={`amount-col ${t.type === 'income' ? 'positive' : ''}`}>{t.type === 'income' ? '+' : '−'}{format(t.amount)}</td><td><div className="row-actions"><IconButton title="Edit transaction" onClick={() => open('transactions', t)}><Pencil size={14} /></IconButton><IconButton title="Delete transaction" onClick={() => remove('transactions', t)}><Trash2 size={14} /></IconButton></div></td></tr>;
    })}</tbody></table></div>;
  }

  function spendingChart() {
    return !grouped.length ? <Empty title="Your spending, untangled" text="A category breakdown will appear as you add expenses." /> : <div className="spending-breakdown"><div className="donut-wrap"><ResponsiveContainer width="100%" height={205}><PieChart><Pie data={grouped} dataKey="value" innerRadius={68} outerRadius={92} paddingAngle={4} stroke="none">{grouped.map((item, index) => <Cell key={item.name} fill={palette[index % palette.length]} />)}</Pie><Tooltip formatter={(value) => format(value)} /></PieChart></ResponsiveContainer><div className="donut-center"><span>Total spent</span><strong>{format(spending, true)}</strong></div></div><div className="category-legend">{grouped.slice(0, 5).map((item, index) => <div key={item.name}><span className="legend-label"><i style={{ background: palette[index % palette.length] }} />{item.name}</span><strong>{format(item.value)}</strong><small>{Math.round(item.value / spending * 100)}%</small></div>)}</div></div>;
  }

  function goalCard(goal, index) {
    const progress = data.progress[goal.id] ?? 0;
    const totalProgress = data.totalProgress?.[goal.id] ?? progress;
    const percent = progress / (goal.targetAmount || 1) * 100;
    const entries = [...(goal.contributions ?? [])].sort((a, b) => b.date.localeCompare(a.date));
    return <article className="goal-card" key={goal.id}><div className="goal-top"><span className={`goal-icon tone-${index % 3}`}>{goal.purpose === 'debt' ? <Landmark size={20} /> : <Target size={20} />}</span><span className="tag">{goal.type === 'monthly' ? 'Monthly' : goal.type === 'deadline' ? 'Deadline' : 'At your pace'}</span></div><h3>{goal.name}</h3><p>{goal.purpose === 'debt' ? 'Paid off' : 'Saved'} <strong>{format(progress)}</strong> <span>of {format(goal.targetAmount)}{goal.type === 'monthly' ? ' this month' : ''}</span></p>{goal.type === 'monthly' && <p className="goal-total-fund">Total fund <strong>{format(totalProgress)}</strong></p>}<p className="goal-total-fund">{goal.purpose === 'debt' ? 'Debt remaining' : 'Counts toward net worth'} <strong>{goal.purpose === 'debt' ? format(Math.max(0, goal.targetAmount - totalProgress)) : format(Math.max(0, totalProgress))}</strong></p><Progress value={percent} tone={`tone-${index % 3}`} /><div className="goal-bottom"><span>{Math.round(percent)}% complete {goal.type === 'monthly' ? 'this month' : ''}</span><span>{goal.status === 'active' ? goal.deadline ? `By ${goal.deadline}` : 'Keep going ✨' : goal.status}</span></div><details className="record-log"><summary>Progress log · {entries.length}</summary>{entries.length ? <ul>{entries.map((entry) => <li key={entry.id}><time>{entry.date}</time><span>{entry.amount < 0 ? goal.purpose === 'debt' ? 'Debt increased / correction' : 'Withdrawal / correction' : goal.purpose === 'debt' ? 'Paid down' : 'Added to fund'}</span><strong className={entry.amount < 0 ? 'expense-color' : 'positive'}>{entry.amount < 0 ? '−' : '+'}{format(Math.abs(entry.amount))}</strong></li>)}</ul> : <p>No progress entries yet.</p>}</details>{page === 'Goals' && <div className="card-actions">{goal.status === 'active' && <button className="button secondary small" onClick={() => open('contribution', goal)}><Plus size={14} /> {goal.purpose === 'debt' ? 'Log progress' : 'Add progress'}</button>}<IconButton title="Edit goal" onClick={() => open('goals', goal)}><Pencil size={15} /></IconButton><IconButton title="Delete goal" onClick={() => remove('goals', goal)}><Trash2 size={15} /></IconButton></div>}</article>;
  }

  return <div className="app-shell">
    {mobileMenu && <button className="sidebar-overlay" aria-label="Close navigation" onClick={() => setMobileMenu(false)} />}
    <aside className={`sidebar ${mobileMenu ? 'is-open' : ''}`}><a className="brand" href="#" onClick={(e) => { e.preventDefault(); navigate('Overview'); }}><span className="brand-icon"><Wallet size={24} /></span>pocket<span className="brand-dot">.</span></a><div className="workspace-label">YOUR PERSONAL SPACE</div><nav aria-label="Main navigation">{navigation.map(({ name, icon: Icon }) => <button key={name} className={`nav-item ${page === name ? 'active' : ''}`} onClick={() => navigate(name)} aria-current={page === name ? 'page' : undefined}><Icon size={19} /><span>{name}</span>{page === name && <span className="nav-dot" />}</button>)}</nav><div className="sidebar-bottom"><div className="privacy-note"><ShieldCheck size={21} /><strong>Just yours. Always.</strong><p>Stored on your server, protected by your owner login. No bank logins. No noise.</p><span>OWNER PROTECTED <i /></span></div><button className="theme-button" onClick={() => setDark(!dark)}>{dark ? <Sun size={17} /> : <Moon size={17} />} {dark ? 'Light appearance' : 'Dark appearance'}</button><div className="profile"><span className="avatar">AD</span><div><strong>Akash Dey</strong><small>Personal account</small></div><span className="profile-dot" /></div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><IconButton title="Open navigation" className="icon-button mobile-toggle" onClick={() => setMobileMenu(true)}><Menu size={21} /></IconButton><span>My workspace</span><span className="breadcrumb-slash">/</span><strong>{page}</strong></div><div className="topbar-right"><span className="local-status"><i /> Owner-only access</span><button className="button secondary small" onClick={signOut} disabled={signingOut}>{signingOut ? 'Signing out…' : 'Sign out'}</button><span className="avatar small-avatar">AD</span></div></header>
      <main><div className="page-heading"><div><div className="eyebrow">A LITTLE CLARITY GOES A LONG WAY</div><h1>{page === 'Overview' ? 'Your money, in perspective.' : page}</h1><p>{({ Overview: 'Welcome back, Akash. Let’s make room for what matters.', Transactions: 'The little things add up. Keep track of every one.', Budgets: 'A plan for today. A little breathing room for tomorrow.', Goals: 'Big dreams, small steps. You’ve got this.', Investments: 'A long-term view of everything you’re building.', Accounts: 'All your accounts. One clear picture.', Reports: 'Find the patterns behind your financial habits.' })[page]}</p></div><div className="heading-actions"><div className="month-picker"><IconButton title="Previous month" onClick={() => moveMonth(-1)}><ChevronLeft size={16} /></IconButton><label><span className="sr-only">Selected month</span><input type="month" min="2000-01" max="2100-12" value={month} onChange={(e) => { if (/^(20\d{2}|2100)-(0[1-9]|1[0-2])$/.test(e.target.value)) setMonth(e.target.value); }} /></label><IconButton title="Next month" onClick={() => moveMonth(1)}><ChevronRight size={16} /></IconButton></div><button className="button primary" onClick={addTransaction}><Plus size={17} /> Add transaction</button></div></div>
      {error && <div className="alert error" role="alert">{error}<IconButton title="Dismiss error" onClick={() => setError('')}><X size={17} /></IconButton></div>}
      {notice && <div className="toast" role="status"><Check size={17} />{notice}</div>}
      {!data ? <div className="loading">{error ? 'The app couldn’t connect. Make sure the backend is running.' : 'Getting your financial picture ready…'}</div> : <>
        {!data.accounts.length && <div className="welcome-banner"><div><Sparkles size={22} /><div><strong>Make yourself at home.</strong><p>{import.meta.env.PROD ? 'Start by adding an account to bring your finances into focus.' : 'Start with an account, or explore Pocket with sample data.'}</p></div></div><div className="inline-actions">{!import.meta.env.PROD && <button className="button secondary small" disabled={busy} onClick={() => run(() => request('/demo', 'POST', {}), 'Sample data loaded. These are demo records, not your real finances.')}>Try demo data</button>}<button className="button primary small" onClick={() => open('accounts')}>Add an account <ArrowRight size={14} /></button></div></div>}
        {page === 'Overview' && <>
          <section className="metrics-grid" aria-label="Financial summary"><article className="metric-card featured"><div className="metric-top"><span>Total net worth</span><span className="metric-icon"><Wallet size={19} /></span></div><strong className="metric-value">{format(netWorth, true)}</strong><div className="metric-foot"><span className="light-pill">The bigger picture</span><span>All-time · assets − liabilities</span></div><span className="card-circle circle-one" /><span className="card-circle circle-two" /></article><article className="metric-card"><div className="metric-top"><span>Income</span><span className="metric-icon green"><ArrowDownLeft size={20} /></span></div><strong className="metric-value">{format(income, true)}</strong><div className="metric-foot"><span className="positive"><ArrowDownLeft size={14} /> Money coming in</span><span>This month</span></div></article><article className="metric-card"><div className="metric-top"><span>Expenses</span><span className="metric-icon peach"><ArrowUpRight size={20} /></span></div><strong className="metric-value">{format(spending, true)}</strong><div className="metric-foot"><span className="expense-color"><ArrowUpRight size={14} /> Mindfully spent</span><span>This month</span></div></article><article className="metric-card"><div className="metric-top"><span>Left to save</span><span className="metric-icon lavender"><PiggyBank size={20} /></span></div><strong className="metric-value">{format(income - spending, true)}</strong><div className="metric-foot"><span className={income - spending >= 0 ? 'positive' : 'expense-color'}>{income ? `${Math.round((income - spending) / income * 100)}% savings rate` : 'Your next chapter'}</span><span>This month</span></div></article></section>
          <section className="overview-middle"><article className="panel cashflow-panel"><PanelHeading title="Money in, money out" subtitle="A little awareness makes a big difference." action={<div className="chart-key"><span><i className="green-dot" />Income</span><span><i className="gold-dot" />Expenses</span></div>} /><div className="cashflow-chart"><ResponsiveContainer width="100%" height={235}><AreaChart data={chartData} margin={{ top: 16, right: 10, bottom: 0, left: 5 }}><defs><linearGradient id="incomeGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#29856b" stopOpacity={0.16} /><stop offset="100%" stopColor="#29856b" stopOpacity={0} /></linearGradient><linearGradient id="expenseGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#dab47b" stopOpacity={0.14} /><stop offset="100%" stopColor="#dab47b" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} strokeDasharray="4 5" stroke="var(--chart-grid)" /><XAxis dataKey="day" tickLine={false} axisLine={false} minTickGap={35} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickFormatter={(day) => `${day} ${new Date(`${month}-02`).toLocaleString('en', { month: 'short' })}`} /><YAxis tickLine={false} axisLine={false} width={52} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickFormatter={(value) => value >= 1000 ? `${Math.round(value / 1000)}k` : value} /><Tooltip formatter={(value) => format(value)} labelFormatter={(day) => `${day} ${monthLabel(month)}`} /><Area type="monotone" dataKey="Income" stroke="#29856b" fill="url(#incomeGradient)" strokeWidth={2.5} /><Area type="monotone" dataKey="Expenses" stroke="#dab47b" fill="url(#expenseGradient)" strokeWidth={2.5} /></AreaChart></ResponsiveContainer></div><div className="chart-footer"><span><span className="subtle-dot" /> Cumulative cash flow · {monthLabel(month)}</span><button className="text-button" onClick={() => navigate('Reports')}>View report <ArrowUpRight size={14} /></button></div></article><article className="panel"><PanelHeading title="Where it went" subtitle="Every expense has a story." action={<IconButton title="View spending report" onClick={() => navigate('Reports')}><ArrowUpRight size={19} /></IconButton>} />{spendingChart()}</article></section>
          <section className="budget-strip"><div className="budget-strip-icon"><Wallet size={25} /></div><div className="budget-copy"><strong>{budget ? budget.remaining >= 0 ? 'A little room to breathe.' : 'Time for a small course correction.' : 'Give your money a little direction.'}</strong><p>{budget ? <>{format(budget.remaining)} left in your {monthLabel(month)} budget. Surplus or deficit rolls into next month.</> : 'Set a monthly budget. We’ll take care of the carryover.'}</p></div>{budget && <div className="budget-mini"><div><strong>{format(budget.spent)}</strong><span>of {format(budget.available)}</span></div><Progress value={budget.available > 0 ? budget.spent / budget.available * 100 : 100} /></div>}<button className="text-button" onClick={() => navigate('Budgets')}>Manage budget <ArrowRight size={17} /></button></section>
          <section className="panel recent-panel"><PanelHeading title="Recent transactions" subtitle="The latest little moves." action={<button className="text-button" onClick={() => navigate('Transactions')}>View all transactions <ArrowRight size={15} /></button>} />{transactionTable([...selected].sort((a, b) => b.date.localeCompare(a.date)), 5)}</section>
          <section className="goals-section"><PanelHeading title="Making room for your dreams" subtitle="Progress is progress, no matter how small." action={<button className="text-button" onClick={() => navigate('Goals')}>All goals <ArrowRight size={15} /></button>} /><div className="goals-grid">{activeGoals.slice(0, 3).map(goalCard)}{activeGoals.length === 0 && <button className="goal-add" onClick={() => open('goals')}><Plus size={24} /><strong>What are you working toward?</strong><span>Create your first savings or debt goal</span></button>}</div></section>
        </>}
        {page === 'Transactions' && <><div className="section-toolbar"><span>Create and reuse your own transaction categories.</span><div className="inline-actions"><button className="button secondary" onClick={() => open('transfer')} disabled={!data.accounts.length}><ArrowLeftRight size={16} /> Transfer</button><button className="button secondary" onClick={() => open('categories')}><Plus size={16} /> Add category</button></div></div>
          <section className="smart-entry">
            <div><Sparkles size={22} /><div><strong>A quicker way to keep track</strong><p>Try “Spent 450 on groceries from HDFC Bank on {today()}”. Review before saving.</p></div></div>
            <form onSubmit={async (e) => { e.preventDefault(); if (busy) return; setBusy(true); try { const draft = await request('/smart-entry', 'POST', { input: smartInput }); open('transactions', { ...draft, draft: true }); } catch (e) { setError(e.message); } finally { setBusy(false); } }}><label className="sr-only" htmlFor="smart-input">Describe a transaction</label>
              <input id="smart-input" value={smartInput} onChange={(e) => setSmartInput(e.target.value)} placeholder="Describe a transaction in your own words…" required maxLength={500} />
              <button className="button primary" disabled={busy || !data.accounts.length}>Review entry <ArrowRight size={16} /></button></form>
              <small>Local rule-based suggestions, not an AI service. ISO dates (YYYY-MM-DD) supported; other dates default to today.</small></section>
              <section className="panel">
                <PanelHeading title="Your transactions" subtitle={`${filtered.length} records · ${monthLabel(month)}`} action={<a className="button secondary small" href={exportHref}><Download size={15} /> Export CSV</a>} />
                <div className="filters">
                  <label className="search-field"><Search size={17} /><input aria-label="Search transactions" placeholder="Search your transactions…" value={search} onChange={(e) => setSearch(e.target.value)} /></label>
                  <select aria-label="Filter by type" value={transactionType} onChange={(e) => setTransactionType(e.target.value)}><option value="">All types</option><option value="income">Income</option><option value="expense">Expense</option><option value="transfer">Transfer</option></select>
                  <select aria-label="Filter by category" value={category} onChange={(e) => setCategory(e.target.value)}><option value="">All categories</option>{[...new Set([...data.categories, 'Transfer'])].map((c) => <option key={c}>{c}</option>)}</select>
                  <select aria-label="Filter by account" value={accountId} onChange={(e) => setAccountId(e.target.value)}><option value="">All accounts</option>{data.accounts.map((a) => <option value={a.id} key={a.id}>{a.name}</option>)}</select>
                  <select aria-label="Filter by investment" value={investmentId} onChange={(e) => setInvestmentId(e.target.value)}><option value="">All investments</option>{data.investments.filter((i) => i.type === 'asset').map((i) => <option value={i.id} key={i.id}>{i.name}</option>)}</select>
                </div>
                {transactionTable(filtered)}
              </section></>}
              {page === 'Budgets' && <section className="panel category-budgets-panel">
                <div className="section-toolbar"><span>Plan a monthly limit across one or more transaction categories.</span><button className="button primary" onClick={() => open('categoryBudgets', { month, categories: [] })}><Plus size={16} /> Create budget</button></div>
                {data.categoryBudgetStatus.length ? <div className="category-budget-grid">{data.categoryBudgetStatus.map((item) => { const matchedTransactions = selected.filter((transaction) => transaction.type === 'expense' && (item.categories.includes('All') || item.categories.includes(transaction.category))).sort((a, b) => b.date.localeCompare(a.date));
                  const monthAdjustments = (item.adjustments ?? []).filter((adjustment) => adjustment.month === month);
                  return <article className="category-budget-card" key={item.id}>
                    <div className="category-budget-heading"><div><span className="eyebrow">STARTED {monthLabel(item.startsAt).toUpperCase()}</span><h3>{item.name}</h3></div>
                    <div className="row-actions"><button className="button secondary small" onClick={() => open('budgetAdjustment', { id: item.id, name: item.name, month })}>Adjust total</button><IconButton title="Edit budget" onClick={() => open('categoryBudgets', item)}><Pencil size={14} /></IconButton><IconButton title="Delete budget" onClick={() => remove('categoryBudgets', item)}><Trash2 size={14} /></IconButton></div></div>
                    <div className="category-budget-tags">{item.categories.map((name) => <span className="tag" key={name}>{name}</span>)}</div>
                    <div className="category-budget-numbers"><span><strong>{format(item.spent)}</strong> spent</span><span>of {format(item.available)}</span></div>
                    <Progress value={item.available > 0 ? item.spent / item.available * 100 : item.spent > 0 ? 100 : 0} tone={item.remaining < 0 ? 'danger' : ''} />
                    <div className="category-budget-foot"><span>{format(item.remaining)} remaining</span><span>Monthly limit {format(item.base)}</span></div>
                    <details className="record-log"><summary>Transaction &amp; adjustment log · {matchedTransactions.length + monthAdjustments.length}</summary>{matchedTransactions.length || monthAdjustments.length ? <ul>{monthAdjustments.map((adjustment) => <li key={adjustment.id}><time>{adjustment.month}</time><span>Total adjustment{adjustment.note ? ` · ${adjustment.note}` : ''}</span><strong className={adjustment.amount < 0 ? 'expense-color' : 'positive'}>{adjustment.amount < 0 ? '−' : '+'}{format(Math.abs(adjustment.amount))}</strong></li>)}{matchedTransactions.map((transaction) => <li key={transaction.id}><time>{transaction.date}</time><span>{transaction.category}{transaction.notes ? ` · ${transaction.notes}` : ''}{data.accounts.find((account) => account.id === transaction.accountId)?.name ? ` · ${data.accounts.find((account) => account.id === transaction.accountId).name}` : ''}</span><strong>{format(transaction.amount)}</strong></li>)}</ul> : <p>No matching expenses or adjustments in {monthLabel(month)}.</p>}</details>
                  </article>; })}</div> : <Empty title="Give your categories a plan" text="Create budgets like Essentials for Food, Utilities, and Rent. Spending is combined across the categories you choose." action={<button className="button secondary" onClick={() => open('categoryBudgets', { month, categories: [] })}><Plus size={16} /> Create budget</button>} />}</section>}
              {page === 'Goals' && <><div className="section-toolbar"><span>{activeGoals.length} active goals · Monthly progress shown for {monthLabel(month)}</span><button className="button primary" onClick={() => open('goals')}><Plus size={16} /> Create a goal</button></div>
                <p className="helper-note">Savings goal balances add to net worth; debt goals subtract the unpaid balance. Goal entries are virtual and do not move account cash, so avoid recording the same funds or debt in both places.</p>
                <div className="goals-grid">{data.goals.map(goalCard)}<button className="goal-add" onClick={() => open('goals')}><Plus size={25} /><strong>Make room for something good</strong><span>Set a savings or debt-payoff goal</span></button></div></>}
              {page === 'Accounts' && <><div className="section-toolbar"><span>Live balances · all recorded transactions, across all dates</span><button className="button primary" onClick={() => open('accounts')}><Plus size={16} /> Add account</button></div>
                <div className="accounts-grid">{data.accounts.map((a, index) => {
                  const flow = accountFlow(a.id, transactions, month);
                  return <article className="panel account-card" key={a.id}>
                    <div className="account-card-top"><span className={`goal-icon tone-${index % 3}`}><Landmark size={22} /></span><span className="tag">{a.type}</span></div>
                    <h2>{a.name}</h2><span className="muted">Current balance</span><div className="big-number">{format(data.balances[a.id])}</div>
                    <p className="account-flow-period">Activity · {monthLabel(month)}</p>
                    <div className="account-flow" aria-label={`${a.name} monthly activity`}>
                      <span>Income<strong className="positive">+{format(flow.income)}</strong></span>
                      <span>Expenses<strong>−{format(flow.expenses)}</strong></span>
                      <span>Transfers in<strong className="positive">+{format(flow.transfersIn)}</strong></span>
                      <span>Transfers out<strong>−{format(flow.transfersOut)}</strong></span>
                    </div>
                    <div className="card-actions"><small>Opening: {format(a.openingBalance)}</small><IconButton title="Edit account" onClick={() => open('accounts', a)}><Pencil size={16} /></IconButton><IconButton title="Delete account" onClick={() => remove('accounts', a)}><Trash2 size={16} /></IconButton></div>
                  </article>;
                })}</div></>}
              {page === 'Investments' && <><section className="metrics-grid three"><article className="metric-card featured"><div className="metric-top">Total net worth<TrendingUp size={20} /></div><div className="metric-value">{format(netWorth)}</div><span className="metric-foot">Accounts + holdings + savings goals − debts</span></article><article className="metric-card"><div className="metric-top">Investment assets<ChartNoAxesCombined size={20} /></div><div className="metric-value">{format(assets)}</div><span className="metric-foot">Manual valuations · not live market data</span></article><article className="metric-card"><div className="metric-top">Outstanding liabilities<Landmark size={20} /></div><div className="metric-value">{format(liabilities)}</div><span className="metric-foot">Avoid duplicating debt in account balances</span></article></section><section className="panel"><PanelHeading title="Your portfolio" subtitle="Keep investment assets separate from bank balances to avoid double-counting." action={<button className="button primary small" onClick={() => open('investments')}><Plus size={16} /> Add holding</button>} />{!data.investments.length ? <Empty title="Build your long-term picture" text="Add an investment, property, or liability to track your net worth." /> : <div className="table-scroll"><table><thead><tr><th>Holding</th><th>Type</th><th>Cost / principal</th><th>Current value</th><th>Gain / loss</th><th>Start date</th><th>Valuation date</th><th>Actions</th></tr></thead><tbody>{data.investments.map((i) => <tr key={i.id}><td><strong>{i.name}</strong></td><td><span className="tag">{i.type}</span></td><td>{format(i.cost)}</td><td>{format(i.value)}</td><td className={i.value - i.cost >= 0 ? 'positive' : 'expense-color'}>{i.type === 'asset' ? `${format(i.value - i.cost)}${i.cost ? ` (${((i.value - i.cost) / i.cost * 100).toFixed(1)}%)` : ''}` : '—'}</td><td>{i.startDate ?? i.date}</td><td>{i.date}</td><td><div className="row-actions"><IconButton title="Edit holding" onClick={() => open('investments', i)}><Pencil size={16} /></IconButton><IconButton title="Delete holding" onClick={() => remove('investments', i)}><Trash2 size={16} /></IconButton></div></td></tr>)}</tbody></table></div>}</section>{data.investments.length > 0 && <section className="panel"><PanelHeading title="Valuation history" subtitle="Every change is saved. Edit a holding to record a new valuation." /><div className="table-scroll"><table><thead><tr><th>Holding</th><th>Valuation date</th><th>Recorded value</th></tr></thead><tbody>{data.investments.flatMap((i) => [...i.history].reverse().map((entry, index) => <tr key={`${i.id}-${index}`}><td>{i.name}</td><td>{entry.date}</td><td>{format(entry.value)}</td></tr>))}</tbody></table></div></section>}</>}
              {page === 'Reports' && <><section className="two-column"><article className="panel"><PanelHeading title="Spending by category" subtitle={monthLabel(month)} />{spendingChart()}</article><article className="panel"><PanelHeading title="A few things worth noticing" subtitle="Simple insights, grounded in your own data." /><div className="insight-list"><div><PiggyBank size={22} /><p>{income > spending ? <>You kept <strong>{format(income - spending)}</strong> of this month’s income. That’s room for future you.</> : income === spending ? 'Your income and spending are balanced this month.' : <>Expenses exceed income by <strong>{format(spending - income)}</strong> this month. Check if a one-off cost explains the gap.</>}</p></div>{grouped[0] && <div><ShoppingBag size={22} /><p><strong>{grouped[0].name}</strong> is your largest spending category at {Math.round(grouped[0].value / spending * 100)}% of expenses.</p></div>}<div><Sparkles size={22} /><p>{data.insights.anomalies.length ? `${data.insights.anomalies.length} unusually large expense(s) are flagged in Transactions. Each is more than twice the recent category average (minimum 3 prior records).` : 'No unusual expenses detected against your recent category averages. More history makes this check more useful.'}</p></div><div><TrendingUp size={22} /><p>{(() => { const [year, number] = month.split('-').map(Number); const previous = number === 1 ? `${year - 1}-12` : `${year}-${String(number - 1).padStart(2, '0')}`;
        const lastSpent = sum(transactions.filter((t) => t.type === 'expense' && t.date.startsWith(previous)));
        return lastSpent ? `Spending is ${Math.abs((spending - lastSpent) / lastSpent * 100).toFixed(0)}% ${spending >= lastSpent ? 'higher' : 'lower'} than the previous month. Compare complete months for a fair picture.` : 'Add last month’s transactions to unlock a month-over-month spending comparison.'; })()}</p></div></div></article></section><section className="panel"><PanelHeading title="By account" subtitle={`Income and spending · ${monthLabel(month)}`} action={<a className="button secondary small" href={`/api/export?month=${month}`}><Download size={15} /> Export month</a>} /><div className="report-chart"><ResponsiveContainer width="100%" height={280}><BarChart data={data.accounts.map((a) => ({ name: a.name, Income: sum(selected.filter((t) => t.accountId === a.id && t.type === 'income')), Expenses: sum(selected.filter((t) => t.accountId === a.id && t.type === 'expense')) }))}><CartesianGrid vertical={false} stroke="var(--chart-grid)" /><XAxis dataKey="name" tick={{ fill: 'var(--muted)', fontSize: 12 }} /><YAxis tick={{ fill: 'var(--muted)', fontSize: 11 }} tickFormatter={(v) => v >= 1000 ? `${v / 1000}k` : v} /><Tooltip formatter={(value) => format(value)} /><Legend /><Bar dataKey="Income" fill="#25876c" radius={[5, 5, 0, 0]} /><Bar dataKey="Expenses" fill="#edb86e" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div></section></>}
              <footer className="page-footer"><span><Leaf size={13} /> Small steps. A healthier financial life.</span><span>Made for your peace of mind. <ShieldCheck size={13} /></span></footer>
            </>}
            </main>
          </div>
          {modal && <Editor modal={modal} data={data} month={month} onClose={() => setModal(null)} onSaved={async () => { await reload(); setNotice('Saved. Your financial picture is up to date.'); setModal(null); }} />}
        </div>;
    }

    function Editor({ modal, data, month, onClose, onSaved }) {
        const { kind, value } = modal;
        const dialog = useRef(null);
        const [error, setError] = useState('');
        const [saving, setSaving] = useState(false);
        const defaults = {
            accounts: { name: '', type: 'bank', openingBalance: 0 },
            transactions: { type: 'expense', date: today(), amount: '', category: 'Food', accountId: data.accounts[0]?.id ?? '', notes: '' },
            transfer: { type: 'transfer', date: today(), amount: '', receivedAmount: '', from: data.accounts[0] ? `account:${data.accounts[0].id}` : '', to: '', notes: '' },
            budgets: { month, amount: '' },
            categoryBudgets: { name: '', month, amount: '', categories: [], carryoverEnabled: true, includeInTotal: true },
            budgetAdjustment: { month: value?.month ?? month, amount: '', note: '' },
            categories: { name: '' },
            goals: { name: '', type: 'unlimited', purpose: 'savings', targetAmount: '', deadline: '', status: 'active' },
            investments: { name: '', type: 'asset', value: '', cost: '', startDate: value?.startDate ?? value?.date ?? today(), date: today(), notes: '' },
            contribution: { amount: '', date: today() },
            delete: {},
        };
        const [form, setForm] = useState({ ...defaults[kind], ...(kind !== 'contribution' && kind !== 'delete' && kind !== 'budgetAdjustment' ? value : {}) });
        useEffect(() => { const element = dialog.current; element.showModal(); const cancel = (e) => { e.preventDefault(); if (!saving) onClose(); }; element.addEventListener('cancel', cancel); return () => element.removeEventListener('cancel', cancel); }, [onClose, saving]);
        const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
        const titles = { accounts: 'account', transactions: 'transaction', transfer: 'transfer', categoryBudgets: 'budget', categories: 'category', goals: 'goal', investments: 'holding', budgetAdjustment: 'budget total' };
        const title = kind === 'delete' ? 'Delete this record?' : kind === 'contribution' ? `Add progress · ${value.name}` : kind === 'budgetAdjustment' ? `Adjust total · ${value.name}` : `${value?.id ? 'Edit' : value?.draft ? 'Review' : 'New'} ${titles[kind]}`;
        const field = (key, label, type = 'text', options) => <label className="form-field" key={key}><span>{label}</span>{options ? <select value={form[key] ?? ''} onChange={(e) => update(key, e.target.value)} required>{options.map((o) => <option key={typeof o === 'string' ? o : o.value} value={typeof o === 'string' ? o : o.value}>{typeof o === 'string' ? o[0].toUpperCase() + o.slice(1) : o.label}</option>)}</select> : type === 'textarea' ? <textarea value={form[key] ?? ''} onChange={(e) => update(key, e.target.value)} maxLength={1000} rows={3} /> : <input type={type} value={form[key] ?? ''} onChange={(e) => update(key, e.target.value)} required={key !== 'deadline' || form.type === 'deadline'} {...(type === 'number' ? { step: '0.01', min: ['openingBalance'].includes(key) || ['contribution', 'budgetAdjustment'].includes(kind) ? -1000000000 : ['cost', 'value'].includes(key) ? 0 : 0.01, max: 1000000000 } : type === 'date' ? { min: '2000-01-01', max: '2100-12-31' } : type === 'month' ? { min: '2000-01', max: '2100-12' } : { maxLength: 120 })} />}</label>;
        const save = async (e) => {
            e.preventDefault(); if (saving) return;
            setSaving(true); setError('');
            try {
                if (kind === 'delete') await request(`/${value.kind}/${value.item.id}`, 'DELETE', {});
                else if (kind === 'contribution') await request(`/goals/${value.id}/contributions`, 'POST', { amount: Number(form.amount), date: form.date });
                else if (kind === 'budgetAdjustment') await request(`/categoryBudgets/${value.id}/adjustments`, 'POST', { ...form, amount: Number(form.amount) });
                else if (kind === 'transfer') {
                    const [fromType, fromId] = form.from.split(':');
                    const [toType, toId] = form.to.split(':');
                    await request('/transactions', 'POST', { type: 'transfer', fromType, fromId, toType, toId, amount: Number(form.amount), ...(fromType === 'investment' ? { receivedAmount: Number(form.receivedAmount) } : {}), date: form.date, notes: form.notes });
                }
                else {
                    const body = { ...form };
                    for (const key of ['amount', 'openingBalance', 'targetAmount', 'value', 'cost']) if (key in body) body[key] = Number(body[key]);
                    if (kind === 'goals') body.deadline = body.type === 'deadline' ? body.deadline || null : null;
                    await request(`/${kind}${value?.id ? `/${value.id}` : ''}`, value?.id ? 'PUT' : 'POST', body);
                }
                await onSaved();
            } catch (e) { setError(e.message); } finally { setSaving(false); }
        };
        return <dialog className="editor-dialog" ref={dialog} aria-labelledby="editor-title"><form onSubmit={save}><div className="dialog-heading"><div><span className="eyebrow">A LITTLE STEP FORWARD</span><h2 id="editor-title">{title}</h2></div><IconButton title="Close dialog" type="button" onClick={onClose} disabled={saving}><X size={20} /></IconButton></div>{error && <div className="alert error" role="alert">{error}</div>}<div className="form-fields">
            {kind === 'accounts' && <>{field('name', 'Bank / account name')}{field('type', 'Account type', 'select', ['bank', 'cash', 'credit', 'savings'])}{field('openingBalance', 'Opening balance (₹) · negative balances supported', 'number')}<p className="helper-note">Credit account debt should be a negative balance. Don’t add the same debt again as an investment liability.</p></>}
            {kind === 'transfer' && <>
                <label className="form-field"><span>From</span><select required value={form.from} onChange={(e) => setForm((current) => ({ ...current, from: e.target.value, to: '', receivedAmount: '' }))}><option value="">Choose source</option><optgroup label="Accounts">{data.accounts.map((a) => <option key={a.id} value={`account:${a.id}`}>{a.name}</option>)}</optgroup><optgroup label="Investment assets">{data.investments.filter((i) => i.type === 'asset').map((i) => <option key={i.id} value={`investment:${i.id}`}>{i.name}</option>)}</optgroup></select></label>
                {field('to', 'To', 'select', [{ value: '', label: 'Choose destination' }, ...data.accounts.map((a) => ({ value: `account:${a.id}`, label: `Account · ${a.name}` })), ...(!form.from.startsWith('investment:') ? data.investments.filter((i) => i.type === 'asset').map((i) => ({ value: `investment:${i.id}`, label: `Investment · ${i.name}` })) : [])].filter((option) => option.value !== form.from))}
                {field('amount', form.from.startsWith('investment:') ? 'Amount deducted from investment (₹)' : 'Amount transferred (₹)', 'number')}
                {form.from.startsWith('investment:') && <label className="form-field"><span>Amount received in bank (₹)</span><input type="number" required min="0" max="1000000000" step="0.01" value={form.receivedAmount} onChange={(e) => update('receivedAmount', e.target.value)} /></label>}
                {field('date', 'Transfer date', 'date')}{field('notes', 'Notes (optional)', 'textarea')}
                <p className="helper-note">Transfers appear in Transactions but do not count as income, spending, or budget expenses. Investment withdrawals reduce cost basis proportionally. Both sides save together. Transfers are read-only after saving; review carefully.</p>
            </>}
            {kind === 'transactions' && <>{value?.draft && <p className="helper-note">Suggested locally from your description. Check the amount, account, category, and date before saving.</p>}
                <div className="form-row">{field('type', 'Transaction type', 'select', ['expense', 'income'])}{field('amount', 'Amount (₹)', 'number')}</div>
                <div className="form-row">{field('date', 'Date', 'date')}{field('accountId', 'Account', 'select', [{ value: '', label: 'Choose an account' }, ...data.accounts.map((a) => ({ value: a.id, label: a.name }))])}</div>
                <label className="form-field"><span>Category</span><select value={form.category} onChange={(e) => update('category', e.target.value)} required>{data.categories.map((name) => <option key={name} value={name}>{name}</option>)}</select></label>{field('notes', 'Description / notes', 'textarea')}</>}
            {kind === 'categories' && <>{field('name', 'Category name')}<p className="helper-note">Your category will be available when adding transactions and building budgets.</p></>}
            {kind === 'categoryBudgets' && <>{field('name', 'Budget name')}{field('month', 'Starts from', 'month')}{field('amount', 'Monthly limit (₹)', 'number')}<fieldset className="form-field category-fieldset"><legend>Categories included</legend><div className="category-checks">{['All', ...data.categories.filter((name) => name !== 'Salary')].map((name) => <label className="category-choice" key={name}><input type="checkbox" checked={form.categories.includes(name)} onChange={(event) => update('categories', name === 'All' ? event.target.checked ? ['All'] : [] : event.target.checked ? [...form.categories.filter((item) => item !== 'All'), name] : form.categories.filter((item) => item !== name))} />{name}</label>)}</div></fieldset><label className="category-choice"><input type="checkbox" checked={form.carryoverEnabled !== false} onChange={(event) => update('carryoverEnabled', event.target.checked)} />Carry unused/overspent balance into the next month</label><label className="category-choice"><input type="checkbox" checked={form.includeInTotal !== false} onChange={(event) => update('includeInTotal', event.target.checked)} />Include this budget in the Overview total</label><p className="helper-note">The limit applies to spending in the selected categories. Choose All to include every expense category, including categories you create later. Categories can be included in more than one budget. Turning off carryover resets each month to its limit.</p></>}
            {kind === 'goals' && <>{field('name', 'What are you working toward?')}<div className="form-row">{field('purpose', 'Goal purpose', 'select', [{ value: 'savings', label: 'Savings' }, { value: 'debt', label: 'Debt payoff' }])}{field('type', 'Timeline', 'select', [{ value: 'monthly', label: 'Monthly · resets each month' }, { value: 'deadline', label: 'Target date' }, { value: 'unlimited', label: 'No deadline' }])}</div>{field('targetAmount', form.type === 'monthly' ? 'Monthly target (₹)' : 'Target amount (₹)', 'number')}{form.type === 'deadline' && field('deadline', 'Target date', 'date')}{field('status', 'Status', 'select', ['active', 'achieved', 'abandoned'])}<p className="helper-note">{form.type === 'monthly' ? 'Monthly progress resets each month. Total fund shows all positive and negative progress adjustments across all months.' : 'Goal progress includes signed adjustments, so negative progress can correct a previous entry.'} Contributions don’t move money or change account balances.</p></>}
            {kind === 'investments' && <>{field('name', 'Holding / liability name')}{field('type', 'Type', 'select', ['asset', 'liability'])}<div className="form-row">{field('cost', 'Cost basis / original principal (₹)', 'number')}{field('value', 'Current value / outstanding amount (₹)', 'number')}</div><div className="form-row">{field('startDate', 'Start date', 'date')}{field('date', 'Valuation date', 'date')}</div>{field('notes', 'Notes', 'textarea')}<p className="helper-note">Each value change is saved to history. Bank balances and these holdings should not overlap.</p></>}
            {kind === 'contribution' && <>{field('amount', value.purpose === 'debt' ? 'Progress adjustment (₹)' : 'Progress adjustment (₹)', 'number')}{field('date', 'Progress date', 'date')}<p className="helper-note">Use a negative amount to reduce the recorded progress or correct an earlier entry. This updates the goal only; it doesn’t transfer funds or change account balances.</p></>}
            {kind === 'budgetAdjustment' && <>{field('month', 'Adjustment month', 'month')}{field('amount', 'Add / remove from available total (₹)', 'number')}<label className="form-field"><span>Note (optional)</span><input type="text" value={form.note} onChange={(event) => update('note', event.target.value)} maxLength={240} /></label><p className="helper-note">Enter a positive amount to add to the available total or a negative amount to remove from it. The recurring monthly limit stays unchanged.</p></>}
            {kind === 'delete' && <p className="delete-copy">This permanently deletes the record and recalculates affected balances and budget carryover. This action can’t be undone.</p>}
            </div><div className="dialog-footer"><button className="button secondary" type="button" onClick={onClose} disabled={saving}>Cancel</button><button className={`button ${kind === 'delete' ? 'danger-button' : 'primary'}`} type="submit" disabled={saving}>{saving ? 'Saving…' : kind === 'delete' ? 'Delete record' : 'Save changes'}{kind !== 'delete' && <Check size={16} />}</button></div></form></dialog>;
    }

    createRoot(document.getElementById('root')).render(<AuthGate>{(auth) => <App {...auth} />}</AuthGate>);